\begin{theorem}[Protected replacement on a torus slab]
\label{thm:prime-index-one}
\uses{thm:prime-maximal-cut}
\lean{PoincareMT.M76.hasHamiltonProtectedIrreducibleReplacement_of_card_eq_one}
For $i=1$, the retained atlas makes the whole handle irreducible,
including after reattachment of the same marked ball. Both PL identity
maps hold near the ball and the complete old boundary.
\end{theorem}

